export type MetadataData = {
    body?: never;
    path: {
        /**
         * The match ID
         */
        match_id: number;
    };
    query?: {
        is_custom?: boolean | null;
        /**
         * If `true`, skip the Steam fallback when the metadata is not available in S3
         * and return an error instead.
         */
        disable_steam?: boolean | null;
    };
    url: '/v1/matches/{match_id}/metadata';
};

export type MetadataErrors = {
    /**
     * Provided parameters are invalid.
     */
    400: unknown;
    /**
     * Match metadata not found
     */
    404: unknown;
    /**
     * Rate limit exceeded
     */
    429: unknown;
    /**
     * Fetching or parsing match metadata failed
     */
    500: unknown;
};

export type MetadataResponses = {
    /**
     * Match metadata, see protobuf type: CMsgMatchMetaDataContents
     */
    200: unknown;
};

export type SteamData = {
    body?: never;
    path?: never;
    query: {
        /**
         * Comma separated list of account ids, Account IDs are in `SteamID3` format.
         */
        account_ids: Array<number>;
        /**
         * Refresh the listed profiles from the Steam Web API before returning.
         */
        refresh?: boolean;
    };
    url: '/v1/players/steam';
};

export type SteamErrors = {
    /**
     * Provided parameters are invalid.
     */
    400: unknown;
    /**
     * No Steam profile found.
     */
    404: unknown;
    /**
     * Rate limit exceeded (only enforced when refresh=true).
     */
    429: unknown;
    /**
     * Failed to fetch steam profiles.
     */
    500: unknown;
    /**
     * Steam Web API call failed (only when refresh=true).
     */
    502: unknown;
};

export type SteamResponses = {
    /**
     * Steam Profiles
     */
    200: Array<SteamProfile>;
};

export type SteamResponse = SteamResponses[keyof SteamResponses];

export type SteamSearchData = {
    body?: never;
    path?: never;
    query: {
        /**
         * Search query for Steam profiles.
         */
        search_query: string;
        /**
         * Maximum number of profiles to return.
         */
        limit?: number | null;
        /**
         * Only return profiles that have played at least this many matches in the
         * last 30 days. Defaults to 5 to filter out inactive/empty profiles and
         * keep search responsive.
         */
        min_matches_played_last_30d?: number | null;
        /**
         * Only return profiles whose `last_team_avg_badge` is at least this
         * value. Defaults to 0 (no filter). Profiles with no recorded badge are
         * stored as 0 and are excluded when this is set above 0.
         */
        min_last_team_avg_badge?: number | null;
        /**
         * Weight applied to `log1p(matches_played_last_30d)` when reranking
         * candidates. The final score per profile is
         * `jaro_winkler(personaname_lc, query) + weight * log1p(matches_played)`.
         * Set to 0 to rank purely by string similarity; raise it to bias toward
         * active/popular players.
         */
        matches_played_weight?: number | null;
    };
    url: '/v1/players/steam-search';
};

export type SteamSearchErrors = {
    /**
     * Provided parameters are invalid.
     */
    400: unknown;
    /**
     * No Steam profiles found.
     */
    404: unknown;
    /**
     * Failed to fetch steam profiles.
     */
    500: unknown;
};

export type SteamSearchResponses = {
    /**
     * Steam Profile Search
     */
    200: Array<SteamProfile>;
};

export type SteamSearchResponse = SteamSearchResponses[keyof SteamSearchResponses];

export type MatchHistoryData = {
    body?: never;
    path: {
        /**
         * The players `SteamID3`
         */
        account_id: number;
    };
    query?: {
        /**
         * Refetch the match history from Steam, even if it is already cached in `ClickHouse`.
         * Only use this if you are sure that the data in `ClickHouse` is outdated.
         * Enabling this flag results in a strict rate limit.
         */
        force_refetch?: boolean;
    };
    url: '/v1/players/{account_id}/match-history';
};

export type MatchHistoryErrors = {
    /**
     * Provided parameters are invalid.
     */
    400: unknown;
    /**
     * Rate limit exceeded. Returns stored match history from ClickHouse as a fallback. When `force_refetch=true`, returns an error instead.
     */
    429: Array<PlayerMatchHistoryEntry>;
    /**
     * Fetching player match history failed
     */
    500: unknown;
};

export type MatchHistoryError = MatchHistoryErrors[keyof MatchHistoryErrors];

export type MatchHistoryResponses = {
    /**
     * OK
     */
    200: Array<PlayerMatchHistoryEntry>;
};

export type MatchHistoryResponse = MatchHistoryResponses[keyof MatchHistoryResponses];

